#include <Adafruit_NeoPixel.h>
#include <math.h>

#define LED_PIN     6
#define LED_COUNT   30
#define BUTTON_PIN  2

Adafruit_NeoPixel strip(
  LED_COUNT,
  LED_PIN,
  NEO_GRB + NEO_KHZ800
);

// --------------------------------------------------
// Настройки
// --------------------------------------------------

uint8_t brightness = 100;

uint8_t red   = 255;
uint8_t green = 0;
uint8_t blue  = 0;

uint8_t mode = 1;

unsigned long lastUpdate = 0;
uint16_t effectStep = 0;

// Кнопка
bool lastButtonState = HIGH;
bool buttonState = HIGH;

unsigned long lastDebounceTime = 0;
const unsigned long debounceDelay = 50;

// Serial
String inputString = "";

// --------------------------------------------------
// SETUP
// --------------------------------------------------

void setup() {

  Serial.begin(115200);

  // Кнопка подключена между D2 и GND
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  strip.begin();
  strip.clear();
  strip.setBrightness(brightness);
  strip.show();

  randomSeed(analogRead(A0));

  Serial.println("NeoPixel Controller Ready");
  Serial.println("Button: D2 -> GND");
}

// --------------------------------------------------
// LOOP
// --------------------------------------------------

void loop() {

  // Управление через ПК
  readSerial();

  // Управление кнопкой
  readButton();

  // Скорость обновления эффектов
  if (millis() - lastUpdate < 20)
    return;

  lastUpdate = millis();

  switch (mode) {

    case 0:
      effectOff();
      break;

    case 1:
      effectRainbow();
      break;

    case 2:
      effectBreath();
      break;

    case 3:
      effectFire();
      break;

    case 4:
      effectOcean();
      break;

    case 5:
      effectLightning();
      break;

    case 6:
      effectTwinkle();
      break;

    case 7:
      effectPolice();
      break;

    case 8:
      effectRainbowChase();
      break;

    case 9:
      effectSolid(255, 0, 0);
      break;

    case 10:
      effectSolid(0, 255, 0);
      break;

    case 11:
      effectSolid(0, 0, 255);
      break;

    case 12:
      effectSolid(255, 255, 255);
      break;
  }

  effectStep++;
}

// ==================================================
// КНОПКА
// ==================================================

void readButton() {

  bool reading = digitalRead(BUTTON_PIN);

  // Состояние изменилось
  if (reading != lastButtonState) {

    lastDebounceTime = millis();
  }

  // Состояние стабильно достаточно долго
  if ((millis() - lastDebounceTime) > debounceDelay) {

    if (reading != buttonState) {

      buttonState = reading;

      // Кнопка нажата
      if (buttonState == LOW) {

        nextMode();
      }
    }
  }

  lastButtonState = reading;
}

// --------------------------------------------------
// Следующий режим
// --------------------------------------------------

void nextMode() {

  mode++;

  // После 12 возвращаемся к 1
  if (mode > 12)
    mode = 1;

  effectStep = 0;

  strip.clear();
  strip.show();

  Serial.print("MODE: ");
  Serial.println(mode);
}

// ==================================================
// SERIAL
// ==================================================

void readSerial() {

  while (Serial.available()) {

    char c = Serial.read();

    if (c == '\n' || c == '\r') {

      if (inputString.length() > 0) {

        processCommand(inputString);

        inputString = "";
      }

    } else {

      inputString += c;
    }
  }
}

// ==================================================
// SERIAL COMMANDS
// ==================================================

void processCommand(String command) {

  command.trim();

  // -----------------------------------------------
  // MODE X
  // -----------------------------------------------

  if (command.startsWith("MODE")) {

    int newMode;

    if (sscanf(command.c_str(), "MODE %d", &newMode) == 1) {

      if (newMode >= 0 && newMode <= 12) {

        mode = newMode;

        effectStep = 0;

        strip.clear();
        strip.show();

        Serial.print("MODE: ");
        Serial.println(mode);
      }
    }
  }

  // -----------------------------------------------
  // BRIGHTNESS X
  // -----------------------------------------------

  else if (command.startsWith("BRIGHTNESS")) {

    int value;

    if (sscanf(command.c_str(), "BRIGHTNESS %d", &value) == 1) {

      value = constrain(value, 0, 255);

      brightness = value;

      strip.setBrightness(brightness);

      Serial.print("BRIGHTNESS: ");
      Serial.println(brightness);
    }
  }

  // -----------------------------------------------
  // COLOR R G B
  // -----------------------------------------------

  else if (command.startsWith("COLOR")) {

    int r, g, b;

    if (sscanf(
      command.c_str(),
      "COLOR %d %d %d",
      &r,
      &g,
      &b
    ) == 3) {

      red   = constrain(r, 0, 255);
      green = constrain(g, 0, 255);
      blue  = constrain(b, 0, 255);

      Serial.print("COLOR: ");
      Serial.print(red);
      Serial.print(" ");
      Serial.print(green);
      Serial.print(" ");
      Serial.println(blue);
    }
  }

  // -----------------------------------------------
  // OFF
  // -----------------------------------------------

  else if (command == "OFF") {

    mode = 0;

    strip.clear();
    strip.show();

    Serial.println("OFF");
  }
}

// ==================================================
// EFFECT 0 — OFF
// ==================================================

void effectOff() {

  strip.clear();
  strip.show();
}

// ==================================================
// EFFECT 1 — RAINBOW
// ==================================================

void effectRainbow() {

  for (int i = 0; i < LED_COUNT; i++) {

    uint16_t hue =
      ((uint32_t)i * 65536 / LED_COUNT
      + effectStep * 256) % 65536;

    strip.setPixelColor(
      i,
      strip.gamma32(strip.ColorHSV(hue))
    );
  }

  strip.show();
}

// ==================================================
// EFFECT 2 — BREATH
// ==================================================

void effectBreath() {

  float x =
    (sin(effectStep * 0.05) + 1.0) / 2.0;

  uint8_t level = x * 255;

  uint8_t r =
    ((uint16_t)red * level) / 255;

  uint8_t g =
    ((uint16_t)green * level) / 255;

  uint8_t b =
    ((uint16_t)blue * level) / 255;

  for (int i = 0; i < LED_COUNT; i++) {

    strip.setPixelColor(
      i,
      strip.Color(r, g, b)
    );
  }

  strip.show();
}

// ==================================================
// EFFECT 3 — FIRE
// ==================================================

void effectFire() {

  for (int i = 0; i < LED_COUNT; i++) {

    int heat = random(100, 256);

    int r = heat;
    int g = heat * 0.35;
    int b = heat * 0.03;

    strip.setPixelColor(
      i,
      strip.Color(r, g, b)
    );
  }

  strip.show();
}

// ==================================================
// EFFECT 4 — OCEAN
// ==================================================

void effectOcean() {

  for (int i = 0; i < LED_COUNT; i++) {

    uint16_t hue =
      45000 +
      sin((effectStep + i * 10) * 0.05) * 5000;

    strip.setPixelColor(
      i,
      strip.gamma32(strip.ColorHSV(hue))
    );
  }

  strip.show();
}

// ==================================================
// EFFECT 5 — LIGHTNING
// ==================================================

void effectLightning() {

  if (random(0, 100) < 8) {

    uint8_t flash = random(150, 256);

    for (int i = 0; i < LED_COUNT; i++) {

      strip.setPixelColor(
        i,
        strip.Color(flash, flash, flash)
      );
    }

    strip.show();
  }
  else {

    strip.clear();
    strip.show();
  }
}

// ==================================================
// EFFECT 6 — TWINKLE
// ==================================================

void effectTwinkle() {

  for (int i = 0; i < LED_COUNT; i++) {

    if (random(0, 100) < 8) {

      strip.setPixelColor(
        i,
        strip.Color(
          random(100, 256),
          random(100, 256),
          random(100, 256)
        )
      );
    }
    else {

      uint32_t color =
        strip.getPixelColor(i);

      uint8_t r = (color >> 16) & 0xFF;
      uint8_t g = (color >> 8) & 0xFF;
      uint8_t b = color & 0xFF;

      r *= 0.8;
      g *= 0.8;
      b *= 0.8;

      strip.setPixelColor(
        i,
        strip.Color(r, g, b)
      );
    }
  }

  strip.show();
}

// ==================================================
// EFFECT 7 — POLICE
// ==================================================

void effectPolice() {

  bool phase =
    (effectStep / 10) % 2;

  for (int i = 0; i < LED_COUNT; i++) {

    if (phase) {

      if (i < LED_COUNT / 2)
        strip.setPixelColor(
          i,
          strip.Color(255, 0, 0)
        );
      else
        strip.setPixelColor(
          i,
          strip.Color(0, 0, 0)
        );

    }
    else {

      if (i >= LED_COUNT / 2)
        strip.setPixelColor(
          i,
          strip.Color(0, 0, 255)
        );
      else
        strip.setPixelColor(
          i,
          strip.Color(0, 0, 0)
        );
    }
  }

  strip.show();
}

// ==================================================
// EFFECT 8 — RAINBOW CHASE
// ==================================================

void effectRainbowChase() {

  for (int i = 0; i < LED_COUNT; i++) {

    uint16_t hue =
      (i * 65536 / LED_COUNT
      + effectStep * 1000) % 65536;

    strip.setPixelColor(
      i,
      strip.gamma32(strip.ColorHSV(hue))
    );
  }

  strip.show();
}

// ==================================================
// EFFECT 9-12 — SOLID
// ==================================================

void effectSolid(
  uint8_t r,
  uint8_t g,
  uint8_t b
) {

  for (int i = 0; i < LED_COUNT; i++) {

    strip.setPixelColor(
      i,
      strip.Color(r, g, b)
    );
  }

  strip.show();
}
